import{_ as t,H as E,f as a,i as n}from"./chunks/framework.BH2BK_3i.js";const B=JSON.parse('{"title":"21-Sleuth体系架构：为什么微服务架构需要链路追踪？","description":"","frontmatter":{},"headers":[{"level":2,"title":"调用链追踪解决了什么问题","slug":"调用链追踪解决了什么问题","link":"#调用链追踪解决了什么问题","children":[]},{"level":2,"title":"Sleuth 的底层逻辑","slug":"sleuth-的底层逻辑","link":"#sleuth-的底层逻辑","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"SpringCloud微服务项目实战/21-Sleuth体系架构：为什么微服务架构需要链路追踪？.md","filePath":"SpringCloud微服务项目实战/21-Sleuth体系架构：为什么微服务架构需要链路追踪？.md","lastUpdated":1795535212000}'),i={name:"SpringCloud微服务项目实战/21-Sleuth体系架构：为什么微服务架构需要链路追踪？.md"};function p(r,e,l,s,h,u){return E(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="_21-sleuth体系架构-为什么微服务架构需要链路追踪" tabindex="-1">21-Sleuth体系架构：为什么微服务架构需要链路追踪？ <a class="header-anchor" href="#_21-sleuth体系架构-为什么微服务架构需要链路追踪" aria-label="Permalink to &quot;21-Sleuth体系架构：为什么微服务架构需要链路追踪？&quot;">​</a></h1><p>你好，我是姚秋辰。</p><p>俗话说，人非圣贤孰能无过，你有过来我有过，微服务它也有过。所谓“过”，便是这线上环境所发生的 Bug。</p><p>面对线上 Bug 怎么办？有则改之，无则加勉而已。Sentinel 用自己的文治武功替我们搞定了后半句“无则加勉”。那么这前半句“有则改之”，我们该如何下手去改呢？</p><p>请你想一下，在开发小哥改正线上 Bug 之前，咱们是不是需要先找到 Bug 发生的原因呢？所以今天我们就来聊一聊“如何找 Bug”这个话题，且看我是如何使用 Sleuth 提供的“调用链追踪”技术，按图索骥查明 Bug 真相的。</p><p>首先我来带你了解一下调用链追踪要解决的问题。</p><h2 id="调用链追踪解决了什么问题" tabindex="-1">调用链追踪解决了什么问题 <a class="header-anchor" href="#调用链追踪解决了什么问题" aria-label="Permalink to &quot;调用链追踪解决了什么问题&quot;">​</a></h2><p>我们可以想象这样一个场景，你负责的是一个庞大的电商微服务架构系统，每个服务之间都有复杂的上下游调用关系，而且并发量还不小，每秒上万 QPS 不在话下。</p><p>在这个微服务系统中，用户通过浏览器的 H5 页面访问系统，这个用户请求会先抵达微服务网关组件，然后网关再把请求分发给各个微服务。所以你会发现，用户请求从发起到结束要经历很多个微服务的处理，这里面还涉及到消息组件的集成。</p><p>我画了一幅图来展示这个复杂的关系。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/21-Sleuth%25E4%25BD%2593%25E7%25B3%25BB%25E6%259E%25B6%25E6%259E%2584/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/21-Sleuth%25E4%25BD%2593%25E7%25B3%25BB%25E6%259E%25B6%25E6%259E%2584/1.png" alt=""></a></p><p>现在问题来了，突然有一天，有用户上报，说他在页面端看到了一个报错，每次点击下单都会报一个 500 错误。如果问题被交到了你手上，你该怎么排查呢？</p><p>作为开发人员我们知道 500 错误是 Internal Server Error，这个异常可能发生在任何阶段，就算在同一时刻也可能有多条不同服务的 Error 日志。在一个没有链路追踪的微服务系统里，线上 Bug 排查无异于大海捞针，因为你根本无法梳理出一次请求的前后调用链。</p><p>因为缺少订单 ID 之类的唯一主键，你就很难缩小排查范围，只能耗费大量的时间用肉眼走查每一条日志。你需要找到用户所有下单记录的起始 log，从前往后挨个摸排，从蛛丝马迹中梳理服务调用之间的关系并定位最终的问题，可见这种方式十分低效。</p><p>如果你想提高线上异常排查的效率，那么首先要做的一件事就是：将一次调用请求中所有访问到的微服务日志前后串联起来。这就像拔出萝卜带出泥一样，只要你找到了本次调用的任何一条日志，你就可以顺藤摸瓜将前后的关联日志信息全部找到。这就是“调用链追踪”技术要完成的工作了。</p><p>那么调用链追踪是如何实现日志信息串联的呢？简单来说，链路追踪技术会为每次服务调用生成一个全局唯一的 ID（后面我们叫它 Trace ID），从本次服务调用的起点到终点，这个过程中的所有日志信息都会被打上 Trace ID 的烙印。这样一来，根据日志中的 Trace ID，我们就能很清晰地梳理出一次服务请求前后都经过了哪些微服务节点。</p><p>就像下面这张图一样，我们将调用链追踪应用到线上 Bug 排查的场景之后，一整条调用链（实线箭头）已是跃然纸上。我们只要找出当前用户下单请求的任意一条日志，就能根据这条日志中的 Trace ID 将整个调用链拎出来，到底是哪个服务调用环节的异常导致了用户下单失败，我们也就一目了然了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/21-Sleuth%25E4%25BD%2593%25E7%25B3%25BB%25E6%259E%25B6%25E6%259E%2584/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/21-Sleuth%25E4%25BD%2593%25E7%25B3%25BB%25E6%259E%25B6%25E6%259E%2584/2.png" alt=""></a></p><p>到这里，相信你已经对调用链追踪所要解决的问题有了清晰的认识。那么接下来，我就带你了解一下 Spring Cloud 的链路追踪组件 Sleuth 是如何实现链路追踪的，也就是分析它的底层逻辑。</p><h2 id="sleuth-的底层逻辑" tabindex="-1">Sleuth 的底层逻辑 <a class="header-anchor" href="#sleuth-的底层逻辑" aria-label="Permalink to &quot;Sleuth 的底层逻辑&quot;">​</a></h2><p>调用链追踪有两个任务，一是标记出一次调用请求中的所有日志，二是梳理日志间的前后关系。前面我提到了一个 Trace ID，它是用来标记调用链的全局唯一 ID。你一定可以联想到，Trace ID 完成的是第一个任务：标记。不过呢，Trace ID 并不能表达日志信息的前后关系，那么 Sleuth 是如何解决这个问题的呢？</p><p>Sleuth 是通过打入到 Log 中的“卧底”来串联前后日志的。你集成了 Sleuth 组件之后，它会向你的日志中打入三个“特殊标记”，其中一个标记你应该已经清楚了，那便是 Trace ID。剩下的两个标记分别是 Span ID 和 Parent Span ID，这俩用来表示调用的前后顺序关系。</p><p>所谓 Span，它是 Sleuth 下面的一个基本工作单元，当服务请求抵达当前单元时，Sleuth 就会为这个单元分配一个独一无二的 Span ID，并标记单元的开始时间和结束时间，这样就可以记录每个单元的处理用时了。</p><p>而 Parent Span ID 呢，顾名思义，它指向了当前单元的父级单元，也就是上游的调用者。一个环环相扣的调用链就通过 Parent Span ID 被串了起来。</p><p>为了让你更加形象地理解 Trace ID、Span ID 和 Parent Span ID 在调用链中的作用，我画了一个简化了服务调用的模拟流程图，带你梳理每一个调用步骤中的日志标记变化。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/21-Sleuth%25E4%25BD%2593%25E7%25B3%25BB%25E6%259E%25B6%25E6%259E%2584/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/21-Sleuth%25E4%25BD%2593%25E7%25B3%25BB%25E6%259E%25B6%25E6%259E%2584/3.png" alt=""></a></p><p>从上面的图中可以看出，这个服务请求调用了三个微服务，分别为服务 A、服务 B 和服务 C。</p><p>在一条调用链中，不管你调用了多少个微服务，Sleuth 为本次调用生成的全局唯一 Trace ID都会贯穿整个链路，所图中三个微服务所对应的日志 Trace ID 都是 A1。</p><p>由于服务 A 是调用链的起点，所以它并没有父级单元，因此它的 Parent Span ID 为空，而起始单元的 Span ID 和 Trace ID 则是相同的，值都为 A1。</p><p>对于服务 B 来说，它的父级调用单元是服务 A，因此它的 Parent Span ID 指向了服务 A 的Span ID，即 A1；同理，服务 C 的 Parent Span ID 指向了服务 B 的 Span ID，即 B2。</p><p>当然啦，上面的图示只是一个简化的流程，在实际的项目中，一次服务调用可不光只会生成一个 Span。比如说服务 A 请求通过 OpenFeign 组件调用了服务 B，那么服务 A 接收用户请求的过程就是一个单元，而 OpenFeign 组件发起远程调用的过程又是另一个单元。由此可见，单元的颗粒度其实是非常小的，在下节课我再通过实战让你近距离观察调用链中的单元分布。</p><p>通过这些 Sleuth 的特殊标记，我们就可以根据时间顺序，将一次服务请求经过的调用节点都梳理出来，这样你就能迅速发现报错信息发生在哪个阶段。这里我放了一张下节课的剧透图片，这是使用 Zipkin 生成的链路追踪的可视化信息。你可以看出，每个服务调用都以时间先后顺序规整好了，红色的部分就是发生线上 Exception 的服务。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/21-Sleuth%25E4%25BD%2593%25E7%25B3%25BB%25E6%259E%25B6%25E6%259E%2584/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/21-Sleuth%25E4%25BD%2593%25E7%25B3%25BB%25E6%259E%25B6%25E6%259E%2584/4.png" alt=""></a></p><p>除了 Trace 和 Span 之外，Sleuth 还有一个特殊的数据结构，叫做 Annotation，被用来记录一个具体的“事件”。我把 Sleuth 所支持的四种事件做成了一个表格，你可以参考一下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/21-Sleuth%25E4%25BD%2593%25E7%25B3%25BB%25E6%259E%25B6%25E6%259E%2584/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/21-Sleuth%25E4%25BD%2593%25E7%25B3%25BB%25E6%259E%25B6%25E6%259E%2584/5.png" alt=""></a></p><p>在这里我举个例子，来帮你理解怎么使用这四种事件。</p><p>以服务 A 调用服务 B 的场景来说，服务 A 是一个 Client，也就是发起调用的一方，而服务 B是一个 Server，也就是处理请求的一方。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/21-Sleuth%25E4%25BD%2593%25E7%25B3%25BB%25E6%259E%25B6%25E6%259E%2584/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/SpringCloud%E5%BE%AE%E6%9C%8D%E5%8A%A1%E9%A1%B9%E7%9B%AE%E5%AE%9E%E6%88%98/images/21-Sleuth%25E4%25BD%2593%25E7%25B3%25BB%25E6%259E%25B6%25E6%259E%2584/6.png" alt=""></a></p><p>如果你用服务 B 的 ss 减去 sr，你就可以得到请求在服务 B 阶段的处理时间；如果用服务 B的 sr 减去服务 A 的 cs，就可以得到服务 A 到服务 B 之间的网络调用延迟时间；如果用服务 A的 cr 减去 cs，就可以得到当次请求从发起到结束所花费的总时间。</p><p>到这里，相信你已经对 Sleuth 的链路打标原理十分了解了，现在让我们来回顾一下这节课的重点内容吧。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>今天我带你了解了调用链追踪技术，以及它所能解决的问题。其中，我们重点了解了 Sleuth是怎么通过特殊的“标记”来完成链路串联的。其中包括了三个重要的标记，它们分别是 TraceID、Span ID 和 Parent Span ID。Trace ID 为每次调用链赋予了一个全局唯一的 ID 标识，后两个标记将调用链中的各个单元根据时间先后顺序做了串联。</p><p>Sleuth 在调用链追踪的场景下主要完成了“打标”的功能，如果你想要构建一套完整的线上异常排查流程，还是需要借助其它组件给 Sleuth 打打辅助。举个例子，如果你想要通过页面 UI 的方式，直观展示一个服务请求的完整调用链，那么你就需要一些分布式 Tracing 系统的帮助。再比如，如果你想要查询调用链中的具体日志信息，那么你还需要一套日志收集和分词系统，另外再加一个日志查询的 UI 系统。</p><p>我将在后面的两节课中，使用业界主流的 Sleuth + Zikpin + ELK 构建起这套完整的线上异常排查流程。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>通过这节课的内容，我们知道了 Sleuth 的 Trace ID 在每个调用链中都是全局唯一的，这也就说明不管你本次调用链访问了多少个微服务，Sleuth 必须想办法把这个 Trace ID 在调用链中依次传递下去，让每一个微服务都能读到这个 Trace ID。基于这个情况，你能猜想一下，Sleuth 是如何实现标签传递的吗？你可以大胆说出自己的设想，下节课我们就揭晓谜底。</p><p>好啦，这节课就结束啦。欢迎你把这节课分享给更多对 Spring Cloud 感兴趣的朋友。我是姚秋辰，我们下节课再见！</p>',47)])])}const g=t(i,[["render",p]]);export{B as __pageData,g as default};
